/**
 * Glitchhook Image-URL Video SaaS Master Engine v11.0
 */
(function() {
  const CONFIG = {
    mappings: [
  {
    "imageUrl": "https://lh3.googleusercontent.com/d/1r--I_WwVztlHbkYuR1UMFzsMANoghuyc",
    "primaryVideo": "https://files.catbox.moe/4vwi3p.mp4",
    "trustVideo": "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4"
  }
],
    scratchTitle: "কার্ডটি ঘষে গোপন ছাড় বের করুন! ekhoni⚡",
    couponCode: "hasib",
    googleSheetUrl: "https://script.google.com/macros/s/AKfycbxmzdVVcd4iYDJ7FyHYTXAO14yHPBxlvwI_ia52rglzHazWmn5Lfb8FNZrdfBfX-gHv8w/exec"
  };

  let state = {
    popupShown: false,
    clickCount: 0,
    startTime: Date.now(),
    lastScrollY: window.pageYOffset,
    maxScrollDepth: 0
  };

  function sendAnalytics(eventType, extraData = {}) {
    if (CONFIG.googleSheetUrl && !CONFIG.googleSheetUrl.includes("YOUR_GOOGLE")) {
      navigator.sendBeacon(CONFIG.googleSheetUrl, JSON.stringify({
        eventType, pageUrl: window.location.href, timestamp: new Date().toLocaleString(), ...extraData
      }));
    }
  }

  function findCheckoutForm() {
    return document.querySelector('form.checkout, form.woocommerce-checkout, #order-form, .order-form, .checkout-form, form[action*="checkout"]') || document.querySelector('input[name*="phone"], input[type="tel"]')?.closest('form');
  }

  function scrollToCheckout() {
    const form = findCheckoutForm();
    if (form) {
      form.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => form.querySelector('input[type="tel"], input[name*="phone"], input[type="text"]')?.focus(), 400);
    } else {
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    }
  }

  // Inject Checkout Timeline
  function injectWidgets() {
    const form = findCheckoutForm();
    if (!form || document.getElementById('gh-checkout-timeline')) return;
    const widget = document.createElement('div');
    widget.id = "gh-checkout-timeline";
    widget.style.cssText = "background: #18181b; border: 1.5px solid #ffcc00; border-radius: 16px; padding: 16px; margin: 15px 0; color: #fff; font-family: sans-serif; font-size: 13px;";
    widget.innerHTML = '<div style="font-weight: 800; color: #00ffcc; font-size: 14px;">🚚 গ্যারান্টিড এক্সপ্রেস ডেলিভারি!</div><div style="color: #a1a1aa; font-size: 12px; margin-top: 2px;">পণ্য হাতে পেয়ে চেক করে টাকা দিন!</div>';
    form.parentNode.insertBefore(widget, form);
  }

  // Scratch Card Modal
  function triggerScratchCard() {
    if (state.popupShown) return;
    state.popupShown = true;
    const overlay = document.createElement('div');
    overlay.style.cssText = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.9); z-index: 999999; display: flex; align-items: center; justify-content: center; padding: 20px; backdrop-filter: blur(10px);";
    overlay.innerHTML = `
      <div style="background: #18181b; color: #fff; padding: 24px; border-radius: 20px; text-align: center; max-width: 340px; width: 100%; border: 1px solid #ffcc00;">
        <h3 style="margin-bottom: 8px; font-size: 18px; color: #ffcc00;">${CONFIG.scratchTitle}</h3>
        <div style="position: relative; width: 260px; height: 100px; margin: 0 auto 15px auto; border-radius: 12px; overflow: hidden; border: 1px dashed #ffcc00;">
          <div style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: #111; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #00ffcc; font-weight: 900;">
            <span>COUPON: ${CONFIG.couponCode}</span>
          </div>
          <canvas id="gh-canvas" width="260" height="100" style="position: absolute; top:0; left:0; cursor:pointer;"></canvas>
        </div>
        <button id="gh-claim" disabled style="background: #333; color: #888; border: none; padding: 12px; border-radius: 30px; font-weight: 900; width: 100%; cursor: not-allowed;">আগে কার্ডটি ঘষুন 👆</button>
      </div>
    `;
    document.body.appendChild(overlay);

    const canvas = document.getElementById('gh-canvas');
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#71717a'; ctx.fillRect(0, 0, 260, 100);
    ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('✨ এখানে ঘষুন ✨', 130, 55);

    let scratchCount = 0;
    function doScratch(e) {
      const rect = canvas.getBoundingClientRect();
      const x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
      const y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath(); ctx.arc(x, y, 15, 0, Math.PI * 2); ctx.fill();
      scratchCount++;
      if (scratchCount > 20) {
        const btn = document.getElementById('gh-claim');
        btn.disabled = false; btn.style.background = '#ffcc00'; btn.style.color = '#000'; btn.style.cursor = 'pointer'; btn.innerText = 'অর্ডার করুন ⚡';
        btn.onclick = () => { overlay.remove(); scrollToCheckout(); };
      }
    }
    canvas.addEventListener('mousemove', doScratch);
    canvas.addEventListener('touchmove', doScratch);
  }

  // Match Image URLs and Replace with Video Engine
  function initEngine() {
    injectWidgets();
    const allImages = document.querySelectorAll('img');

    allImages.forEach(img => {
      const imgSrc = img.src || img.getAttribute('data-src') || '';
      
      CONFIG.mappings.forEach(map => {
        if (map.imageUrl && imgSrc.includes(map.imageUrl)) {
          const parent = img.parentElement;
          const height = img.clientHeight || 400;
          img.style.display = 'none';

          const wrapper = document.createElement('div');
          wrapper.style.cssText = `position: relative; width: 100%; min-height: ${height}px; background: #000; border-radius: 12px; overflow: hidden; display: flex; align-items: center; justify-content: center; margin-bottom: 12px;`;
          
          wrapper.innerHTML = `
            <video src="${map.primaryVideo}" autoplay muted loop playsinline preload="auto" style="width: 100%; height: 100%; object-fit: cover; position: absolute; top:0; left:0; pointer-events:none;"></video>
            <div style="position: absolute; top:0; left:0; width:100%; height:100%; z-index:10; cursor:pointer;"></div>
            <button style="position: absolute; bottom: 15px; right: 15px; background: #ffcc00; color: #000; border: none; padding: 10px 22px; border-radius: 30px; font-weight: 900; font-size: 13px; cursor: pointer; z-index: 20; box-shadow: 0 4px 15px rgba(0,0,0,0.5);">BUY NOW ⚡</button>
          `;

          const videoEl = wrapper.querySelector('video');
          const buyBtn = wrapper.querySelector('button');
          
          const triggerBuy = (e) => { e.stopPropagation(); state.clickCount++; sendAnalytics("BUY_CLICK"); scrollToCheckout(); };
          buyBtn.onclick = triggerBuy;
          wrapper.onclick = triggerBuy;

          parent.appendChild(wrapper);

          // Scroll listener for video switch & exit pop
          window.addEventListener('scroll', () => {
            let currentY = window.pageYOffset;
            if (currentY > state.maxScrollDepth) state.maxScrollDepth = currentY;

            if (state.maxScrollDepth > 150 && (state.lastScrollY - currentY > 20)) {
              videoEl.src = map.trustVideo;
              videoEl.load();
              videoEl.play().catch(()=>{});
            }

            if (state.maxScrollDepth > 200 && (state.lastScrollY - currentY > 35) && currentY < 150) {
              triggerScratchCard();
            }
            state.lastScrollY = currentY;
          }, { passive: true });
        }
      });
    });
  }

  if (document.readyState === 'complete' || document.readyState === 'interactive') initEngine();
  else document.addEventListener('DOMContentLoaded', initEngine);
})();
